CREATE OR REPLACE FUNCTION public.rsc_fence_loss_correction_seal_0161()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE raw jsonb:=to_jsonb(NEW); body jsonb; actor text; request text; reference text;
    aggregate text; identifier text; hashes text[]; item record;
BEGIN
    IF TG_OP<>'INSERT' OR TG_TABLE_SCHEMA<>'public' THEN
        RAISE EXCEPTION '0161 exact insert fence required' USING ERRCODE='23514'; END IF;
    body:=COALESCE(raw->'after_jsonb',raw->'metadata_jsonb',raw->'payload_jsonb','{}'::jsonb);
    actor:=COALESCE(raw->>'actor_user_id',raw->>'actor_id',body->>'actor_user_id');
    request:=COALESCE(raw->>'request_id',body->>'request_id');
    reference:=COALESCE(raw->>'request_reference',body->>'request_reference');
    aggregate:=COALESCE(raw->>'aggregate_type',raw->>'business_type');
    identifier:=COALESCE(raw->>'aggregate_id',raw->>'business_id');
    hashes:=ARRAY[raw->>'idempotency_key_hash',raw->>'reversal_key_hash',raw->>'approval_key_hash',
        raw->>'correction_key_hash',body->>'reversal_key_hash',body->>'approval_key_hash',body->>'correction_key_hash'];
    IF TG_TABLE_NAME='state_transition_events' AND COALESCE(
        aggregate IN ('authentication_attempt','login_challenge','sms_dispatch','auth_session')
        AND body->>'operation'='formal_authentication_state_transition'
        AND body->>'request_id' ~ '^authreq-[a-f0-9]{64}$'
        AND body->>'request_reference' IS NULL,false) THEN RETURN NULL; END IF;
    IF array_remove(hashes,NULL)='{}'::text[] AND (actor IS NULL OR (request IS NULL AND reference IS NULL))
       AND COALESCE(aggregate,'') NOT IN ('stock_loss_correction_approval_seal','stock_loss_correction_execution_seal')
       AND TG_TABLE_NAME NOT IN ('stock_loss_correction_approval_seals','stock_loss_correction_execution_seals') THEN
        RETURN NULL; END IF;
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0161 seal fence requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0161 seal ledger required' USING ERRCODE='23514'; END IF;
    FOR item IN
        SELECT id,'approval' AS kind FROM public.stock_loss_correction_approval_seals s WHERE
            (TG_TABLE_NAME='stock_loss_correction_approval_seals' AND raw->>'id'=s.id::text)
            OR (aggregate='stock_loss_correction_approval_seal' AND identifier=s.id::text)
            OR ARRAY[s.reversal_key_hash,s.approval_key_hash,s.correction_key_hash]::text[] && hashes
            OR (actor=s.actor_user_id AND (request=s.request_id OR request=s.request_reference OR reference=s.request_reference))
        UNION ALL
        SELECT id,'execution' AS kind FROM public.stock_loss_correction_execution_seals s WHERE
            (TG_TABLE_NAME='stock_loss_correction_execution_seals' AND raw->>'id'=s.id::text)
            OR (aggregate='stock_loss_correction_execution_seal' AND identifier=s.id::text)
            OR ARRAY[s.reversal_key_hash,s.approval_key_hash,s.correction_key_hash]::text[] && hashes
            OR (actor=s.actor_user_id AND (request=s.request_id OR request=s.request_reference OR reference=s.request_reference))
    LOOP
        IF item.kind='approval' THEN PERFORM public.rsc_check_loss_approval_seal_0161(item.id);
        ELSE PERFORM public.rsc_check_loss_execution_seal_0161(item.id); END IF;
    END LOOP;
    IF aggregate IN ('stock_loss_correction_approval_seal','stock_loss_correction_execution_seal') THEN
        IF aggregate='stock_loss_correction_approval_seal' THEN
            PERFORM public.rsc_check_loss_approval_seal_0161(identifier::uuid);
        ELSE PERFORM public.rsc_check_loss_execution_seal_0161(identifier::uuid); END IF;
    END IF;
    RETURN NULL;
END;
$function$

